  "KPI 副标：徽章 + 文本，承载次级信息（严重漏洞数 / 待执行 / 工具数 / 健康度）" = "KPI sub-label: badge + text carrying secondary info (critical vuln count / pending / tool count / health)"
  "「上次更新」徽章" = "Last updated badge"
  "告警条「× 忽略」按钮：低权重，hover 时才显形" = "Alert bar Dismiss button: low weight, only appears on hover"
  "「上次更新」过期状态：变灰 + ⚠️ 图标显形" = "Last updated stale state: grayed out + warning icon appears"
  "推荐操作 section：紧急 / 警告 / 配置 三类，颜色区分但不喧宾夺主" = "Recommended actions section: urgent / warning / config — three types, color-coded but not overpowering"
  "紧急推荐：左侧加红条强调" = "Urgent recommendation: left-side red stripe for emphasis"
  "最近事件 section：列表风格，按 p0/p1/p2 着色" = "Recent events section: list style, colored by p0/p1/p2 priority"
  "External MCP 健康度：能力总览中专门一行的 N/N + 状态徽章" = "External MCP health: a dedicated row in the capability overview showing N/N + status badge"
  "升级版「最近漏洞」空状态：标题 + 描述 + 行动按钮" = "Enhanced recent vulnerabilities empty state: title + description + action button"
  "章节标题 + 「查看全部」链接横排（标题不再单独占下边框）" = "Section title + View all link in a row (title no longer takes up its own border below)"
  "最近漏洞 / 近期事实 Tab" = "Recent vulnerabilities / recent facts tab"
  "置顶 / 分类 / 置信度 / 摘要 / fact_key / 项目 / 时间" = "Pinned / category / confidence / summary / fact_key / project / time"
  "项目：虚线描边 + 浅底，与置信度实心药丸区分" = "Project: dashed border + light background, distinct from the solid confidence pill"
  "最近漏洞列表" = "Recent vulnerabilities list"
  "占满卡片内容宽，避免无 href 的 <a> 或 flex 子项按内容收缩导致右侧大块留白" = "Fill the card content width to avoid right-side whitespace when an anchor without href or a flex child shrinks to content size"
  "状态药丸：和处置状态卡片用同一套语义色，但采用更克制的尺寸" = "Status pill: uses the same semantic colors as the disposition status card, but in a more restrained size"
  "能力总览 - 侧栏列表" = "Capability overview — sidebar list"
  "WebShell 用偏暗的青蓝色，跟`"终端 / shell`"语义对得上，又跟其他几个色相区分" = "WebShell uses a darker teal-blue that matches the terminal/shell semantic and is distinct from the other hues"
  "漏洞严重程度分布：半环形图（浅色风格）" = "Vulnerability severity distribution: half-ring chart (light style)"
  "三列布局：[风险概览卡(结论)] [donut(分布图)] [legend(明细)]" = "Three-column layout: [risk overview card (conclusion)] [donut (distribution chart)] [legend (details)]"
  "结论性信息前置，与右列的分类明细互补。" = "conclusion-type info like how dangerous / how many urgent items remain / when last updated, complementing the right column breakdown details."
  "风险概览卡：竖向堆叠三块小模块（风险等级/加权分/待处理/最新时间）" = "Risk overview card: three small modules stacked vertically (risk level / weighted score / pending / latest time)"
  "—— 风险等级模块 ——" = "—— Risk level module ——"
  "风险等级着色：安全/低/中/高/极高" = "Risk level coloring: safe / low / medium / high / critical"
  "—— 待处理紧急项：分组（标题 + 两个小徽章） ——" = "—— Pending urgent items: grouped (title + two small badges) ——"
  "当数量为 0 时，数值变灰，避免在无紧急项时仍然引人注目" = "When count is 0, the value is grayed out to avoid drawing attention when there are no urgent items"
  "—— 最近发现 ——" = "—— Recent findings ——"
  "半环形主体配色由 SVG linearGradient（#donut-grad-*）提供" = "Half-ring main coloring is provided by SVG linearGradient (#donut-grad-*)"
  "中心数字：纯文字，贴在半圆开口下方（直径线附近），不遮挡彩色弧带" = "Centre number: plain text, positioned just below the semicircle opening (near the diameter line), does not block the colored arc"
  "标签列有上限；末尾 1fr 吸收侧栏余量，空白在百分比右侧而非标签与数字之间" = "Label column has an upper limit; trailing 1fr absorbs sidebar remainder so whitespace is on the right of percentages, not between labels and numbers"
  "漏洞处置状态 + 修复进度（占据 donut 下方留白）" = "Vulnerability disposition status + fix progress (filling the whitespace below the donut)"
  "主内容区：快捷入口横向排列，按钮保持自然宽度不拉伸" = "Main content area: quick-access entries arranged horizontally, buttons maintain natural width without stretching"
  "主内容区快捷入口：去掉图标外层的`"涂层`"，降低按钮高度" = "Main content area quick-access entries: remove the icon wrapper overlay to reduce button height"
  "工具执行次数（仅柱状图）" = "Tool execution count (bar chart only)"
  "尊重用户`"减少动效`"偏好（无障碍最佳实践）" = "Respect the user reduce-motion preference (accessibility best practice)"
  "更多筛选生效数量：弱提示文字" = "Number of active additional filters: subtle hint text"
  "元数据条数为奇数时，最后一项占满一行，长 URL/队列 ID 更易读" = "When the metadata row count is odd, the last item spans a full row so long URLs/queue IDs are more readable"
  "漏洞详情字段：标签与值分行，长 ID/URL 可换行、可选中复制" = "Vulnerability detail fields: label and value on separate lines; long IDs/URLs can wrap and be selected for copying"
  "==================== 攻击链可视化响应式样式 ====================" = "==================== Attack chain visualisation responsive styles ===================="
  "批量队列详情弹窗：即使在窄屏也保持按钮不`"变形`"" = "Batch queue detail modal: prevent buttons from distorting even on narrow screens"
  "与角色选择器共用 .role-selector-btn；此处仅包一层用于定位浮层" = "Shares .role-selector-btn with the role selector; here it only wraps one layer for positioning the floating panel"
  "单/多代理面板：与「选择角色」浮层同一视觉语言（白底、圆角、阴影）" = "Single/multi-agent panel: same visual language as the Select role floating panel (white background, rounded corners, shadow)"
  "选项为 <button>，浏览器默认 text-align:center 会继承到文案，强制左对齐与角色列表一致" = "Options are button elements; the browser defaults text-align:center which inherits to labels — force left-align to match the role list"
  "选项内勾选：未选中时隐藏（与角色列表一致）" = "In-option checkmark: hidden when not selected (consistent with the role list)"
  "主内容区域角色选择面板样式（下拉菜单形式）" = "Role selection panel styles in the main content area (dropdown form)"
  "防止 flex 列容器在高度受限时把列表项纵向压扁（应滚动而非压缩）" = "Prevent the flex column container from vertically compressing list items when height is limited (should scroll, not compress)"
  "在移动设备上限制显示8个角色，每个约60px，总计约480px" = "On mobile, limit to 8 visible roles, each ~60px, total ~480px"
  "在小屏幕上限制显示8个角色，每个约55px，总计约450px" = "On small screens, limit to 8 visible roles, each ~55px, total ~450px"
  "确保列表可以滚动，不会把分页栏推出视口" = "Ensure the list can scroll without pushing the pagination bar out of the viewport"
  "Skills 管理：复用全局页面与列表规范，移除该页独有的渐变/悬浮视觉。" = "Skills management: reuse global page and list conventions; remove the gradient/hover visuals unique to this page."
  "Skills 状态监控：只保留数据展示所需规则，视觉复用通用页面组件。" = "Skills status monitor: keep only the rules needed for data display; reuse generic page component visuals."
  "==================== 信息收集（FOFA）页面 ====================" = "==================== Information collection (FOFA) page ===================="
  "覆盖全局 .form-group textarea(min-height:200px) 的默认大留白" = "Override the default large whitespace of the global .form-group textarea (min-height:200px)"
  "允许在 flex 中收缩，避免撑破布局" = "Allow shrinking in flex layout to prevent breaking the layout"
  "勾选列（左侧固定）" = "Checkbox column (pinned left)"
  "单元格点击展开提示（非强制）" = "Cell click-to-expand hint (non-mandatory)"
  "字段显示/隐藏面板" = "Field show/hide panel"
  "分组视图：外层不再套一层大边框，由各分组卡片承担" = "Group view: no longer wraps in a large outer border; each group card handles its own border"
  "JS 使用 fixed 定位时覆盖 absolute，避免被表格区域 overflow 裁切" = "Override absolute with fixed positioning when JS requires it, to avoid being clipped by table area overflow"
  "文件管理：重命名 / 新建文件夹 — 紧凑表单弹窗，无全局紫色标题条" = "File management: rename / new folder — compact form modal, no global purple title bar"
  "更柔和的滚动条样式" = "Softer scrollbar style"
  "让`"任务执行详情`"视觉上跟随助手气泡宽度，而不是强行 100% 宽" = "Let task execution details visually follow the assistant bubble width instead of forcing 100%"
  "覆盖通用 .process-details-container 的边框/内边距，避免重复一层`"边框卡片`"" = "Override the border/padding of the generic .process-details-container to avoid double-nesting a border card"
  "展开后才把宽度撑满；未展开时保持折叠按钮`"缩回去`"的视觉" = "Only stretch to full width when expanded; keep the collapsed visual for the toggle button when not expanded"
  "让 timeline item 更`"像条目`"而不是松散的分隔块" = "Make timeline items feel more like list entries than loose dividers"
  "避免每条详情都出现内层滚动条（体验会显得很`"碎`"）" = "Avoid an inner scrollbar on every detail entry (it makes the UX feel fragmented)"
  "markdown 里已经有块级元素，不需要再整体 pre-wrap，否则容易在块之间产生`"空行`"感" = "Markdown already has block elements; no need for global pre-wrap, which tends to create an empty-line feel between blocks"
}

foreach ($key in $replacements.Keys) {
  $content = $content.Replace($key, $replacements[$key])
}

# Handle remaining Chinese
$remaining = [regex]::Matches($content, '[\u4e00-\u9fff]+[^\n]*')
Write-Host "Remaining Chinese occurrences: $($remaining.Count)"
foreach ($m in $remaining | Select-Object -First 20) {
  Write-Host "  LINE: $($m.Value)"
}

Set-Content -Path "web\static\css\style.css" -Value $content -Encoding UTF8 -NoNewline
Write-Host "Saved style.css"
